/* ============================ Đô thị ============================ */
export function buildCity() {
  const items: { x: number; z: number; w: number; d: number; h: number; c: number }[] = [];
  const palette = [0xf3f0e7, 0xeae2cf, 0xdadcdc, 0xcfe0e7, 0xdde8df, 0xc8ced4, 0xf6f6f2, 0xe6dccb];
  const avoid = (_x: number, z: number) => Math.abs(z) < 48 || Math.abs(z - CONFIG.ttl.z) < 40;
  const place = (x0: number, x1: number, near: number, beach: boolean) => {
    const step = 36;
    for (let gx = x0; gx < x1; gx += step) for (let gz = -1800; gz < 1800; gz += step) {
      const ix = Math.round(gx / step), iz = Math.round(gz / step);
      if (ix % 5 === 0 || iz % 5 === 0) continue;  // chừa đường phố
      if (avoid(gx, gz) || rand() < 0.16) continue;
      const nearR = 1 - clamp((Math.abs(gx - near)) / 900, 0, 1);
      let h = 9 + rand() * 26 + nearR * rand() * 65 + (rand() < 0.05 ? 55 : 0);
      if (beach && gx > 1290) h = 45 + rand() * 115; // khách sạn ven biển Mỹ Khê
      items.push({ x: gx + (rand() - 0.5) * 6, z: gz + (rand() - 0.5) * 6, w: 14 + rand() * 15, d: 14 + rand() * 15, h, c: palette[Math.floor(rand() * palette.length)] });
    }
  };
  place(-2000, -330, -330, false); // bờ Tây — trung tâm Hải Châu
  place(340, 1450, 340, true);      // bờ Đông — Sơn Trà
  // Gom thành cụm, mỗi cụm là một LOD (gần: có cửa sổ; xa: khối trơn)
  const cell = 900, clusters = new Map<string, typeof items>();
  for (const b of items) { const key = `${Math.floor(b.x / cell)}_${Math.floor(b.z / cell)}`; if (!clusters.has(key)) clusters.set(key, []); clusters.get(key).push(b); }
  const geo = new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0);
  const nearMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.75, metalness: 0.05 });
  patchWindows(nearMat, { perBuilding: true });
  const farMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
  patchFarGlow(farMat);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), col = new THREE.Color();
  for (const list of clusters.values()) {
    const cx = list.reduce((a, b) => a + b.x, 0) / list.length, cz = list.reduce((a, b) => a + b.z, 0) / list.length;
    const near = new THREE.InstancedMesh(geo, nearMat, list.length), far = new THREE.InstancedMesh(geo, farMat, list.length);
    list.forEach((b, i) => {
      m.compose(v.set(b.x - cx, CONFIG.landY, b.z - cz), q, s.set(b.w, b.h, b.d));
      near.setMatrixAt(i, m); far.setMatrixAt(i, m); col.setHex(b.c); near.setColorAt(i, col); far.setColorAt(i, col.multiplyScalar(0.92));
    });
    near.castShadow = true; near.receiveShadow = true;
    const lod = new THREE.LOD(); lod.position.set(cx, 0, cz);
    lod.addLevel(near, 0); lod.addLevel(far, 2200); lod.addLevel(new THREE.Object3D(), 8000);
    scene.add(lod);
  }
}
import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { CONFIG } from '../../config';
import { buildAtlas, type Atlas } from './adAtlas';
import { clearRects, collectBuildings, snapshot, type Rect } from './clearance';
import { buildLandmarks, type Landmarks } from './landmarks';
import { buildHearts, type Hearts } from './heartFacade';
import { buildBillboards, panoRects, type Billboards } from './billboards';
import { buildPromenade, type Promenade } from './promenade';

/* [riverfront] Hai bờ sông Hàn: địa danh thật, mặt dựng LED trái tim + "DN", bảng quảng cáo, chi tiết bờ.
   Gọi buildRiverfront() SAU mọi lệnh dựng có dùng rand() (sau HanTunnel trong main.ts): chỉ thu nhỏ instance nhà/cây bị đè về 0. */
export interface Riverfront {
  group: THREE.Group; atlas: Atlas; landmarks: Landmarks; hearts: Hearts; billboards: Billboards; promenade: Promenade;
  footprints: Rect[]; cleared: { buildings: number; plants: number }; snapshot: typeof snapshot;
  adsEnabled: boolean;
}
let current: Riverfront | null = null;
export const getRiverfront = () => current;

export function buildRiverfront(): Riverfront {
  const group = new THREE.Group(); group.name = 'riverfront';
  const atlas = buildAtlas(), landmarks = buildLandmarks();
  const footprints = [...landmarks.rects, ...panoRects()];
  const cleared = clearRects(footprints, CONFIG.riverfront.clearMargin);
  const buildings = collectBuildings();                    // nhà còn lại sau khi dọn: chọn mái, mặt tiền, cửa hàng từ đây
  const hearts = buildHearts(landmarks.towers);
  const billboards = buildBillboards(atlas, landmarks, buildings);
  const promenade = buildPromenade(atlas, billboards.adMat, buildings);
  group.add(landmarks.mesh, hearts.mesh, billboards.group, promenade.group);
  scene.add(group);
  current = { group, atlas, landmarks, hearts, billboards, promenade, footprints, cleared, snapshot, adsEnabled: true };
  return current;
}
export function updateRiverfront(dt: number, _time: number) {
  if (!current) return;
  current.hearts.update(dt);
  if (current.adsEnabled) { current.billboards.update(dt); current.promenade.update(); }
}
export function setHeartsEnabled(on: boolean) { current?.hearts.setEnabled(on); }
export function setHeartsMode(m: 'duet' | 'sync') { current?.hearts.setMode(m); }
/* "Quảng cáo": bảng quảng cáo + băng rôn + bảng hiệu; không tắt chi tiết bờ (lan can, ghế…) */
export function setAdsEnabled(on: boolean) { if (!current) return; adsWanted = on; applyAds(); }
/* Thời tiết (bão) tắt quảng cáo tạm thời; hết bão trả đúng lựa chọn của người dùng (adsWanted), không ép bật */
export function setAdsSuppressed(on: boolean) { adsSuppressed = on; applyAds(); }
let adsWanted = true, adsSuppressed = false;
function applyAds() { if (!current) return; const on = adsWanted && !adsSuppressed; if (current.adsEnabled === on) return; current.adsEnabled = on; current.billboards.setEnabled(on); }
export function disposeRiverfront() {
  if (!current) return;
  const c = current; c.hearts.dispose(); c.billboards.dispose(); c.promenade.dispose(); c.atlas.dispose();
  c.landmarks.mesh.geometry.dispose(); (c.landmarks.mesh.material as THREE.Material).dispose(); c.group.removeFromParent(); current = null;
}
import * as THREE from 'three';
