function tower(g: THREE.BufferGeometry[], x: number, z: number, w: number, d: number, floors: number, c: C3, podium: number) {
  const H = floors * R.floorH;
  g.push(box(w + podium, 10, d + podium, x, Y, z, STONE));                       // bệ thương mại
